func TestReferenceInfoUserDefinedTypesDefinition(t *testing.T) {
	udtScenario(t, func(c *udtCase) {
		c.exec("CREATE SCHEMA udt_scope", "CREATE TABLE udt_scope.pg_namespace(v integer)", "CREATE TABLE udt_scope.pg_class(v integer)", "CREATE TABLE udt_scope.pg_type(v integer)")
		// Only the three captured class references become qualified under these shadows.
		qualify := strings.NewReplacer("FROM pg_namespace n", "FROM pg_catalog.pg_namespace n", "    pg_class c", "    pg_catalog.pg_class c", "    pg_type t", "    pg_catalog.pg_type t")
		for _, mode := range []struct {
			path           string
			normal, pretty string
		}{
			{"public", udtDefaultDefinition, udtPrettyDefinition},
			{"information_schema,public", udtPathDefinition, udtPrettyPathDefinition},
			{"udt_scope,public,pg_catalog", qualify.Replace(udtDefaultDefinition), qualify.Replace(udtPrettyDefinition)},
		} {
			c.exec("SET search_path=" + mode.path)
			for _, pretty := range []bool{false, true} {
				want := mode.normal
				if pretty {
					want = mode.pretty
				}
				for _, argument := range []string{"'information_schema.user_defined_types'::regclass", "'information_schema.user_defined_types'::text"} {
					s := fixture.Select("SELECT pg_catalog.pg_get_viewdef("+argument+",$1::boolean) AS definition", []string{"definition"}, []string{"TEXT"}, [][]any{{want}}, pretty)
					c.run(s)
					c.run(fixture.Prepared(s))
				}
			}
			for _, argument := range []string{"'information_schema.user_defined_types'::regclass", "'information_schema.user_defined_types'::text"} {
				s := fixture.Select("SELECT pg_catalog.pg_get_viewdef("+argument+") AS definition", []string{"definition"}, []string{"TEXT"}, [][]any{{mode.normal}})
				c.run(s)
				c.run(fixture.Prepared(s))
			}
			s := fixture.Select("SELECT view_definition,check_option,is_updatable,is_insertable_into,is_trigger_updatable,is_trigger_deletable,is_trigger_insertable_into FROM information_schema.views WHERE table_schema='information_schema' AND table_name='user_defined_types'", []string{"view_definition", "check_option", "is_updatable", "is_insertable_into", "is_trigger_updatable", "is_trigger_deletable", "is_trigger_insertable_into"}, []string{"VARCHAR", "VARCHAR", "VARCHAR", "VARCHAR", "VARCHAR", "VARCHAR", "VARCHAR"}, [][]any{{mode.normal, "NONE", "NO", "NO", "NO", "NO", "NO"}})
			c.run(s)
			c.run(fixture.Prepared(s))
		}
		c.exec("RESET search_path")
		for _, pretty := range []bool{false, true} {
			for _, argument := range []string{"'udt_scope.pg_class'::regclass", "'udt_scope.pg_class'::text"} {
				s := fixture.Select("SELECT pg_catalog.pg_get_viewdef("+argument+",$1::boolean) AS definition", []string{"definition"}, []string{"TEXT"}, [][]any{{nil}}, pretty)
				c.run(s)
				c.run(fixture.Prepared(s))
			}
		}
	})
}

